//? run: "200 MHz repeat 1"
//? const: setting = 16779771
//? run: "200 MHz repeat 2"
//? const: setting = 16779771
//? run: "200 MHz repeat 3"
//? const: setting = 16779771

.cogexec
    HUBSET 0xf0
    HUBSET aug(setting & 0xfffffffc)
    WAITX aug(300000)
    HUBSET aug(setting)
    DIRL 40
    WRPIN 0, 40
    OUTH 40
    DIRH 40
    WAITX 32
    OUTL 40
    WAITX 4
    TESTP 40 :wc
    WRC first
    OUTH 40
    WAITX 32
    OUTL 40
    WAITX 5
    MOV second, INB
    SHR second, 8
    AND second, 1
    HUBSET aug(setting & 0xfffffffc)
    HUBSET 0xf0
    WRPIN P_TT_01 | P_ASYNC_TX, 62
    DIRH 62
    MOV PA, first
    CALL send
    MOV PA, second
    CALL send
flush:
    RQPIN PB, 62 :wc
if(C) JMP flush
halt:
    JMP halt
send:
    RQPIN PB, 62 :wc
if(C) JMP send
    WYPIN PA, 62
    RET
var first: LONG 0
var second: LONG 0

